import type { CertificationRequestDraft } from "../CertificationRequestContext";
import type { IdentificatiePersonSubformValue } from "@procertus-ui/domain-certification";
import type { RegistrationEnrichmentHints } from "./lib/vatPrototypePresets";

export type IdentificatiePersonCaptureState = IdentificatiePersonSubformValue;

export type CustomerContext = {
  representativeFirstName: string;
  representativeLastName: string;
  /** Preset id: none, mr, mrs, …, other */
  representativeTitlePreset: string;
  /** Effective title (from preset or free text / override) */
  representativeTitle: string;
  representativeEmail: string;
  /** Preset id for role; `other` means user must type `representativeRole` */
  representativeRolePreset: string;
  /** Required: label from preset or custom text */
  representativeRole: string;
  /** §1 Identificatiefiche — telefoon firma */
  firmaPhone: string;
  /** §1 — telefoon/GSM wettelijke vertegenwoordiger */
  legalRepresentativePhone: string;
  organizationName: string;
  country: string;
  vatNumber: string;
  addressStreet: string;
  addressHouseNumber: string;
  addressPostalCode: string;
  addressCity: string;
  /** Optioneel: ISO 3166-1 alpha-2 (landcode) voor het firma-adres */
  addressCountryCode: string;

  /**
   * §3 — afwijkende verantwoordelijke voor PROCERTUS-certificatie/inspectie
   * (default: wettelijke vertegenwoordiger uit stap Registratie).
   */
  addCertificationContactOverride: boolean;
  certificationContact: IdentificatiePersonCaptureState;

  /** §4 — tweede ontvanger PROCERTUS (optioneel) */
  addCertificationSecondaryContact: boolean;
  certificationSecondary: IdentificatiePersonCaptureState;

  /** §5 — facturatiegegevens (optioneel) */
  addInvoicingDetails: boolean;
  /** Contactpersoon of dienstnaam voor facturatie */
  invoicingContactOrDepartment: string;
  /** Uitgebreide contactpersoon naast het vrije veld */
  invoicingUseContactPerson: boolean;
  invoicingContactPerson: IdentificatiePersonCaptureState;
  invoicingEmail: string;
  /** Facturatieadres enkel indien verschillend van firma-adres */
  addInvoicingAddressOverride: boolean;
  invoicingAddressStreet: string;
  invoicingAddressHouseNumber: string;
  invoicingAddressPostalCode: string;
  invoicingAddressCity: string;
  invoicingCountry: string;
  invoicingAddressCountryCode: string;
};

export const ONBOARDING_STEPS = ["request", "customer", "company", "review", "summary"] as const;

export type OnboardingStep = (typeof ONBOARDING_STEPS)[number];

export type AnonymousOnboardingFlowState = {
  step: OnboardingStep;
  drafts: CertificationRequestDraft[];
  /** Draft ids included in the submission package on the summary step (all drafts stay listed; toggling updates the left overview only). */
  summaryIncludedDraftIds?: string[];
  context: CustomerContext;
  wizardInitialStep: "intent" | "drafts";
  /** Prototype: which canned VAT scenario is selected (production: free-text VAT only). */
  prototypeVatPresetId: string;
  /** Helper copy under company-step fields after mock enrichment; cleared when the user edits that field. */
  companyFieldHints: RegistrationEnrichmentHints;
};

import {
  Field,
  FieldContent,
  FieldDescription,
  FieldLabel,
  Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Switch,
} from "@procertus-ui/ui";
import type { IdentificatiePersonSubformValue } from "@procertus-ui/domain-certification";
import { COUNTRY_SELECT_NONE } from "./anonymous-onboarding-constants";

export type IdentificatieAddressSubformValue = {
  street: string;
  houseNumber: string;
  postalCode: string;
  locality: string;
  country: string;
  countryCode: string;
};

type CountryOption = { value: string; label: string };

/**
 * Herbruikbare blokken in lijn met de identificatiefiche (persoon / adres).
 * Gebruikt voor wettelijke vertegenwoordiger, PROCERTUS-contacten, facturatie, enz.
 */
export function IdentificatieOptionalBlock({
  switchId,
  title,
  description,
  checked,
  onCheckedChange,
  children,
}: {
  switchId: string;
  title: string;
  description?: string;
  checked: boolean;
  onCheckedChange: (next: boolean) => void;
  children: React.ReactNode;
}) {
  return (
    <section
      className="space-y-4 rounded-lg border border-border bg-muted/20 p-4"
      aria-labelledby={`${switchId}-label`}
    >
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0 space-y-1">
          <p id={`${switchId}-label`} className="text-sm leading-snug font-medium text-foreground">
            {title}
          </p>
          {description ? (
            <p className="text-xs leading-relaxed text-muted-foreground">{description}</p>
          ) : null}
        </div>
        <div className="flex shrink-0 items-center gap-2 sm:pt-0.5">
          <span className="text-xs text-muted-foreground sm:sr-only">
            {checked ? "Ingeschakeld" : "Uit"}
          </span>
          <Switch
            id={switchId}
            checked={checked}
            onCheckedChange={(v) => onCheckedChange(v === true)}
            aria-labelledby={`${switchId}-label`}
          />
        </div>
      </div>
      {checked ? <div className="space-y-4 border-t border-border/60 pt-4">{children}</div> : null}
    </section>
  );
}

export function IdentificatiePersonSubform({
  idPrefix,
  value,
  onChange,
  emailHint,
  description,
  requireEmail = true,
}: {
  idPrefix: string;
  value: IdentificatiePersonSubformValue;
  onChange: (next: IdentificatiePersonSubformValue) => void;
  emailHint?: string;
  description?: string;
  requireEmail?: boolean;
}) {
  const patch = (partial: Partial<IdentificatiePersonSubformValue>) =>
    onChange({ ...value, ...partial });

  return (
    <div className="grid gap-4 md:grid-cols-2">
      <Field className="md:col-span-1">
        <FieldLabel htmlFor={`${idPrefix}-firstName`}>Voornaam</FieldLabel>
        <FieldContent>
          <Input
            id={`${idPrefix}-firstName`}
            value={value.firstName}
            onChange={(e) => patch({ firstName: e.target.value })}
            autoComplete="given-name"
          />
        </FieldContent>
      </Field>
      <Field className="md:col-span-1">
        <FieldLabel htmlFor={`${idPrefix}-lastName`}>Achternaam</FieldLabel>
        <FieldContent>
          <Input
            id={`${idPrefix}-lastName`}
            value={value.lastName}
            onChange={(e) => patch({ lastName: e.target.value })}
            autoComplete="family-name"
          />
        </FieldContent>
      </Field>
      <Field className="md:col-span-2">
