import { Globe } from "lucide-react";

import { cn } from "@procertus-ui/ui";

import type { OnboardingRequestOrigin } from "./onboarding-request-origin";

const frame = "shrink-0 overflow-hidden rounded-[3px] shadow-sm ring-1 ring-border/60";

function BeFlag({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 3 2"
      className={cn(frame, "h-6 w-9", className)}
      aria-hidden
    >
      <title>België</title>
      <rect width="1" height="2" fill="#000000" x="0" />
      <rect width="1" height="2" fill="#FDDA24" x="1" />
      <rect width="1" height="2" fill="#EF3340" x="2" />
    </svg>
  );
}

function NlFlag({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 3 2"
      className={cn(frame, "h-6 w-9", className)}
      aria-hidden
    >
      <title>Nederland</title>
      <rect width="3" height="0.6667" y="0" fill="#AE1C28" />
      <rect width="3" height="0.6666" y="0.6667" fill="#FFFFFF" />
      <rect width="3" height="0.6667" y="1.3333" fill="#21468B" />
    </svg>
  );
}

/** Simplified US banner (stripes + union); readable at small sizes. */
function UsFlag({ className }: { className?: string }) {
  const stripes = 13;
  const h = 100 / stripes;
  return (
    <svg
      viewBox="0 0 190 100"
      className={cn(frame, "h-6 w-[2.85rem]", className)}
      aria-hidden
    >
      <title>Verenigde Staten</title>
      {Array.from({ length: stripes }, (_, i) => (
        <rect
          key={i}
          x="0"
          y={(i * 100) / stripes}
          width="190"
          height={h + 0.01}
          fill={i % 2 === 0 ? "#B22234" : "#FFFFFF"}
        />
      ))}
      <rect x="0" y="0" width="76" height={7 * h} fill="#3C3B6E" />
    </svg>
  );
}

/** EU circle of stars — simplified as dots for clarity at small size. */
function EuFlag({ className }: { className?: string }) {
  const r = 22;
  const cx = 30;
  const cy = 30;
  return (
    <svg
      viewBox="0 0 60 60"
      className={cn(frame, "h-6 w-6", className)}
      aria-hidden
    >
      <title>Europees</title>
      <rect width="60" height="60" fill="#003399" rx="3" />
      {Array.from({ length: 12 }, (_, i) => {
        const angle = (i * Math.PI * 2) / 12 - Math.PI / 2;
        return (
          <circle
            key={i}
            cx={cx + r * Math.cos(angle)}
            cy={cy + r * Math.sin(angle)}
            r={2.6}
            fill="#FFCC00"
          />
        );
      })}
    </svg>
  );
}

export function RequestOriginFlag({
  origin,
  className,
}: {
  origin: OnboardingRequestOrigin;
  className?: string;
}) {
  switch (origin) {
    case "be":
      return <BeFlag className={className} />;
    case "nl":
      return <NlFlag className={className} />;
    case "us":
      return <UsFlag className={className} />;
    case "eu":
      return <EuFlag className={className} />;
    case "other":
      return (
        <span
          className={cn(
            "flex size-6 shrink-0 items-center justify-center rounded-[3px] bg-muted/40 ring-1 ring-border/60",
            className,
          )}
          aria-hidden
        >
          <Globe className="size-4 text-muted-foreground" strokeWidth={1.75} />
        </span>
      );
  }
}

