export type OnboardingPackageReviewSegment =
  | { type: "row"; id: string; label: string; value: string }
  | { type: "klantenportaal-toggle"; personId: string; displayName: string };

function pushPackageRow(
  segments: OnboardingPackageReviewSegment[],
  id: string,
  label: string,
  value: string | undefined | null,
) {
  const v = typeof value === "string" ? value.trim() : "";
  segments.push({ type: "row", id, label, value: v.length > 0 ? v : "—" });
}

function pushPersonFieldRows(
  segments: OnboardingPackageReviewSegment[],
  section: string,
  idPrefix: string,
  person: IdentificatiePersonCaptureState,
) {
  pushPackageRow(segments, `${idPrefix}-aanhef`, `${section} · Aanhef/titel`, person.title);
  pushPackageRow(segments, `${idPrefix}-voornaam`, `${section} · Voornaam`, person.firstName);
  pushPackageRow(segments, `${idPrefix}-achternaam`, `${section} · Achternaam`, person.lastName);
  pushPackageRow(segments, `${idPrefix}-email`, `${section} · E-mail`, person.email);
  pushPackageRow(segments, `${idPrefix}-telefoon`, `${section} · Telefoon`, person.telephone);
}

/**
 * Flat list of every captured field for the final-step “full package” table, plus Klantenportaal
 * toggle markers for each {@link CustomerContext.onboardingRegisteredPersons} row.
 */
export function buildFullOnboardingPackageSegments(
  context: CustomerContext,
  drafts: readonly CertificationRequestDraft[],
  includedDraftIds: readonly string[],
  requestOrigin: OnboardingRequestOrigin | "",
): OnboardingPackageReviewSegment[] {
  const segments: OnboardingPackageReviewSegment[] = [];
  const included = drafts.filter((d) => includedDraftIds.includes(d.id));

  const originTitle =
    requestOrigin === ""
      ? ""
      : (ONBOARDING_REQUEST_ORIGIN_OPTIONS.find((o) => o.id === requestOrigin)?.title ?? requestOrigin);
  pushPackageRow(segments, "registratie-origin", "Registratie · Vestigingsland/regio", originTitle);

  pushPackageRow(
    segments,
    "registratie-applicant-lr",
    "Registratie · Ik ben de wettelijke vertegenwoordiger",
    context.applicantIsLegalRepresentative === "yes"
      ? "Ja"
      : context.applicantIsLegalRepresentative === "no"
        ? "Nee"
        : "",
  );

  pushPackageRow(segments, "org-naam", "Organisatie · Bedrijfsnaam", context.organizationName);
  pushPackageRow(segments, "org-btw", "Organisatie · Identificatienummer (btw/kvk/…)", context.vatNumber);
  pushPackageRow(segments, "org-land", "Organisatie · Land (firma-adres)", context.country);
  pushPackageRow(
    segments,
    "org-adres",
    "Organisatie · Adres (straat, huisnr., postcode, plaats)",
    formatPostalAddressDisplay(context),
  );
  pushPackageRow(
    segments,
    "org-landcode",
    "Organisatie · Adres landcode (ISO)",
    context.addressCountryCode,
  );
  pushPackageRow(segments, "org-tel", "Organisatie · Telefoon firma", context.firmaPhone);

  pushPackageRow(
    segments,
    "lr-preset-titel",
    "Wettelijke vertegenwoordiger · Aanhef (voorkeuze-id)",
    context.representativeTitlePreset,
  );
  pushPackageRow(
    segments,
    "lr-preset-functie",
    "Wettelijke vertegenwoordiger · Functie (voorkeuze-id)",
    context.representativeRolePreset,
  );
  pushPersonFieldRows(
    segments,
    "Wettelijke vertegenwoordiger",
    "lr",
    legalRepresentativePersonValue(context),
  );
  pushPackageRow(
    segments,
    "lr-functie-label",
    "Wettelijke vertegenwoordiger · Functie (label)",
    context.representativeRole,
  );

  if (context.applicantIsLegalRepresentative === "no") {
    pushPackageRow(
      segments,
      "ind-preset-titel",
      "Indiener · Aanhef (voorkeuze-id)",
      context.registrantTitlePreset,
    );
    pushPackageRow(
      segments,
      "ind-preset-functie",
      "Indiener · Functie (voorkeuze-id)",
      context.registrantRolePreset,
    );
    pushPersonFieldRows(segments, "Indiener", "ind", registrantPersonFormValue(context));
    pushPackageRow(segments, "ind-functie-label", "Indiener · Functie (label)", context.registrantRole);
  }

  pushPackageRow(
    segments,
    "fact-email",
    "Facturatie · E-mail facturatie",
    context.invoicingEmail,
  );
  pushPackageRow(
    segments,
    "fact-contactpersoon-actief",
    "Facturatie · Uitgebreid contactpersoon actief",
    context.invoicingUseContactPerson ? "Ja" : "Nee",
  );
  if (context.invoicingUseContactPerson) {
    pushPackageRow(
      segments,
      "fact-contact-registry",
      "Facturatie · Contactpersoon (register-id)",
      context.invoicingContactPersonRegistryId,
    );
    pushPersonFieldRows(
      segments,
      "Contactpersoon facturatie",
      "fact-persoon",
      context.invoicingContactPerson,
    );
  }

  pushPackageRow(
    segments,
    "fact-afwijkend-adres",
    "Facturatie · Afwijkend facturatieadres actief",
    context.addInvoicingAddressOverride ? "Ja" : "Nee",
  );
  if (context.addInvoicingAddressOverride) {
    const cap = invoicingAddressCapture(context);
    pushPackageRow(
      segments,
      "fact-adres-regel",
      "Facturatie · Adres (straat huisnr, pc plaats)",
      `${cap.street} ${cap.houseNumber}, ${cap.postalCode} ${cap.locality}`,
    );
    pushPackageRow(segments, "fact-adres-land", "Facturatie · Land", cap.countryLabel);
  }

  pushPackageRow(
    segments,
    "cert-hoofd-actief",
    "Certificatie/inspectie · Hoofdcontact actief",
    context.addCertificationContactOverride ? "Ja" : "Nee",
  );
  if (context.addCertificationContactOverride) {
    pushPackageRow(
      segments,
      "cert-hoofd-registry",
      "Certificatie/inspectie · Hoofdcontact (register-id)",
      context.certificationContactPersonRegistryId,
    );
    pushPackageRow(
      segments,
      "cert-hoofd-titel-preset",
      "Certificatie/inspectie · Hoofd — aanhef (voorkeuze-id)",
      context.certificationContactTitlePreset,
    );
    pushPackageRow(
      segments,
      "cert-hoofd-titel",
      "Certificatie/inspectie · Hoofd — aanhef (tekst)",
      context.certificationContactTitle,
    );
    pushPackageRow(
      segments,
      "cert-hoofd-functie-preset",
      "Certificatie/inspectie · Hoofd — functie (voorkeuze-id)",
      context.certificationContactRolePreset,
    );
    pushPackageRow(
      segments,
      "cert-hoofd-functie",
      "Certificatie/inspectie · Hoofd — functie (tekst)",
      context.certificationContactRole,
    );
    pushPersonFieldRows(
      segments,
      "Certificatie/inspectie · Hoofdcontact",
      "cert-hoofd",
      certificationContactPersonFormValue(context),
    );
  }

  pushPackageRow(
    segments,
    "cert-reserve-actief",
    "Certificatie/inspectie · Reservecontact actief",
    context.addCertificationSecondaryContact ? "Ja" : "Nee",
  );
  if (context.addCertificationSecondaryContact) {
    pushPackageRow(
      segments,
      "cert-reserve-registry",
      "Certificatie/inspectie · Reserve (register-id)",
      context.certificationSecondaryPersonRegistryId,
    );
    pushPackageRow(
      segments,
      "cert-reserve-titel-preset",
      "Certificatie/inspectie · Reserve — aanhef (voorkeuze-id)",
      context.certificationSecondaryTitlePreset,
    );
    pushPackageRow(
      segments,
      "cert-reserve-titel",
      "Certificatie/inspectie · Reserve — aanhef (tekst)",
      context.certificationSecondaryTitle,
    );
    pushPackageRow(
      segments,
      "cert-reserve-functie-preset",
      "Certificatie/inspectie · Reserve — functie (voorkeuze-id)",
      context.certificationSecondaryRolePreset,
    );
    pushPackageRow(
      segments,
      "cert-reserve-functie",
      "Certificatie/inspectie · Reserve — functie (tekst)",
      context.certificationSecondaryRole,
    );
    pushPersonFieldRows(
      segments,
      "Certificatie/inspectie · Reservecontact",
      "cert-reserve",
      certificationSecondaryPersonFormValue(context),
    );
  }

  for (const p of context.onboardingRegisteredPersons) {
    const name = summaryDisplayNameForRegisteredPerson(p);
    pushPackageRow(
      segments,
      `pr-${p.id}-bron`,
      `Personenregister · ${name} · Bronlabel`,
      p.sourceLabel,
    );
    pushPackageRow(
      segments,
      `pr-${p.id}-rollen`,
      `Personenregister · ${name} · Toegewezen rollen`,
      summaryRolesForRegisteredPerson(context, p).join(" · "),
    );
    pushPersonFieldRows(segments, `Personenregister · ${name}`, `pr-${p.id}-data`, p.person);
    segments.push({ type: "klantenportaal-toggle", personId: p.id, displayName: name });
  }

  pushPackageRow(
    segments,
    "pakket-aantal-concepten",
    "Aanvraagpakket · Totaal conceptaanvragen",
    String(drafts.length),
  );
  pushPackageRow(
    segments,
    "pakket-aantal-opgenomen",
    "Aanvraagpakket · Opgenomen in zending",
    String(included.length),
  );

  included.forEach((draft, index) => {
    const n = index + 1;
    pushPackageRow(segments, `draft-${draft.id}-id`, `Aanvraag ${n} · Id`, draft.id);
    pushPackageRow(segments, `draft-${draft.id}-label`, `Aanvraag ${n} · Label`, draft.label);
    pushPackageRow(
      segments,
      `draft-${draft.id}-short`,
      `Aanvraag ${n} · Korte label`,
      draft.shortLabel,
    );
    pushPackageRow(
      segments,
      `draft-${draft.id}-entry`,
      `Aanvraag ${n} · Entry-id`,
      draft.entryId,
    );
    pushPackageRow(
      segments,
      `draft-${draft.id}-product-id`,
      `Aanvraag ${n} · Product-id`,
      draft.productId,
    );
    pushPackageRow(
      segments,
      `draft-${draft.id}-product-label`,
      `Aanvraag ${n} · Productlabel`,
      draft.productLabel,
    );
