    );
  }

  pushPackageRow(segments, "fact-email", "Facturatie · E-mail facturatie", context.invoicingEmail);
  pushPackageRow(
    segments,
    "fact-contactpersoon-actief",
    "Facturatie · Uitgebreid contactpersoon actief",
