  );

  included.forEach((draft, index) => {
    const n = index + 1;
    pushPackageRow(segments, `draft-${draft.id}-id`, `Aanvraag ${n} · Id`, draft.id);
    pushPackageRow(segments, `draft-${draft.id}-label`, `Aanvraag ${n} · Label`, draft.label);
    pushPackageRow(
