      `draft-${draft.id}-short`,
      `Aanvraag ${n} · Korte label`,
      draft.shortLabel,
    );
    pushPackageRow(segments, `draft-${draft.id}-entry`, `Aanvraag ${n} · Entry-id`, draft.entryId);
    pushPackageRow(
      segments,
      `draft-${draft.id}-product-id`,
      `Aanvraag ${n} · Product-id`,
      draft.productId,
    );
    pushPackageRow(
      segments,
      `draft-${draft.id}-product-label`,
      `Aanvraag ${n} · Productlabel`,
      draft.productLabel,
    );
    pushPackageRow(
      segments,
      `draft-${draft.id}-stream`,
      `Aanvraag ${n} · Productstroom`,
      draft.productTypeStreamLabel,
    );
    pushPackageRow(
      segments,
      `draft-${draft.id}-path`,
      `Aanvraag ${n} · Productpad`,
      draft.productPath,
    );
    pushPackageRow(segments, `draft-${draft.id}-value`, `Aanvraag ${n} · Waarde`, draft.value);
    pushPackageRow(segments, `draft-${draft.id}-context`, `Aanvraag ${n} · Context`, draft.context);
  });

  return segments;
}

